Q: Writing edit-form component using form from &quot;create&quot; component A: <p>You don’t need to write a separate form again for the edit page.
The correct approach is to reuse the same form component used in the create page and just pass different props.</p>
<p>Recommended Pattern</p>
<p>Create a reusable form component</p>
<p>Use it in both Create and Edit</p>
<p>In Edit mode, preload existing data</p>
<pre><code>const UserForm = ({ initialValues, onSubmit, isEdit }) =&gt; {
  const [form, setForm] = React.useState(initialValues);

  const handleChange = (e) =&gt; {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  return (
    &lt;form onSubmit={(e) =&gt; { e.preventDefault(); onSubmit(form); }}&gt;
      &lt;input
        name=&quot;name&quot;
        value={form.name}
        onChange={handleChange}
        placeholder=&quot;Name&quot;
      /&gt;
      &lt;button type=&quot;submit&quot;&gt;
        {isEdit ? &quot;Update&quot; : &quot;Create&quot;}
      &lt;/button&gt;
    &lt;/form&gt;
  );
};


const EditUser = ({ user }) =&gt; {
  const handleUpdate = (data) =&gt; {
    // API call for update
  };

  return (
    &lt;UserForm
      initialValues={user}
      onSubmit={handleUpdate}
      isEdit={true}
    /&gt;
  );
};
</code></pre>

